sp_widget.client_script:
api.controller = function($scope) {

    var c = this;

    c.loading = false;


    // =====================================================
    // DEFAULT FILTERS
    // =====================================================

    c.filters = {

        dateRange: "ALL",

        visaType: "ALL",

        caseStatus: "ALL",

        advisor: "ALL",

        risk: "ALL"

    };


    // =====================================================
    // REFRESH
    // =====================================================

    c.refreshReports = function() {

        c.loading = true;

        c.server.get({

            action: "refresh"

        }).then(function(response) {

            c.data = response.data;

            c.loading = false;

        }, function() {

            c.loading = false;

        });

    };


    // =====================================================
    // APPLY FILTERS
    // =====================================================

    c.applyFilters = function() {

        c.loading = true;

        c.server.get({

            action: "filter",

            filters: c.filters

        }).then(function(response) {

            c.data = response.data;

            c.loading = false;

        }, function() {

            c.loading = false;

        });

    };


    // =====================================================
    // REPORT BUTTON
    // =====================================================

    c.generateReport = function(type) {

        c.loading = true;

        c.server.get({

            action: "report",

            reportType: type,

            filters: c.filters

        }).then(function(response) {

            c.data = response.data;

            c.loading = false;

        }, function() {

            c.loading = false;

        });

    };


    // =====================================================
    // INITIAL DATA
    // =====================================================

    if (!c.data) {

        c.server.get({

            action: "refresh"

        }).then(function(response) {

            c.data = response.data;

        });

    }

};

sp_widget.css:
.vg-reports-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI",
    Roboto, Helvetica, Arial, sans-serif;

  color: #2b3674;
  padding: 0px;
}


/* =========================================================
   HERO
   ========================================================= */

.vg-reports-container .vg-hero-banner {
  background: linear-gradient(
    135deg,
    #091e3a 0%,
    #0d3a78 100%
  );

  border-radius: 12px;
  padding: 24px 30px;

  color: #ffffff;

  display: flex;
  justify-content: space-between;
  align-items: center;

  box-shadow: 0 8px 20px rgba(9, 30, 58, 0.15);

  margin-bottom: 24px;
}


.vg-reports-container .hero-content h2 {
  margin: 0 0 6px 0;
  font-weight: 700;
  font-size: 24px;
  color: #ffffff;
}


.vg-reports-container .hero-content p {
  margin: 0;
  font-size: 13px;
  opacity: 0.85;
}


.vg-reports-container .btn-hero-outline {
  border: 1px solid rgba(255,255,255,0.4);

  background: rgba(255,255,255,0.08);

  color: #ffffff;

  font-weight: 600;
  font-size: 13px;

  padding: 8px 18px;

  border-radius: 8px;

  transition: all 0.2s ease;
}


.vg-reports-container .btn-hero-outline:hover {
  background: #ffffff;
  color: #0d3a78;
}


/* =========================================================
   COLORS
   ========================================================= */

.vg-reports-container .text-blue {
  color: #0066ff;
}

.vg-reports-container .text-orange {
  color: #ff9f43;
}

.vg-reports-container .text-green {
  color: #00b074;
}

.vg-reports-container .text-red {
  color: #ea5455;
}

.vg-reports-container .text-navy {
  color: #1b2559;
}


/* =========================================================
   KPI CARDS
   ========================================================= */

.vg-reports-container .metric-row {
  margin-bottom: 24px;
}


.vg-reports-container .vg-metric-card {
  background: #ffffff;

  border-radius: 12px;

  padding: 18px 20px;

  display: flex;
  align-items: center;

  gap: 16px;

  box-shadow: 0 4px 15px rgba(0,0,0,0.03);

  border: 1px solid #eef2f7;

  min-height: 94px;
}


.vg-reports-container .metric-icon {
  width: 52px;
  height: 52px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 20px;

  flex-shrink: 0;
}


.vg-reports-container .green-circle {
  background: #e6f4ea;
  color: #00b074;
}


.vg-reports-container .red-circle {
  background: #fde8e8;
  color: #ea5455;
}


.vg-reports-container .blue-circle {
  background: #e8f0fe;
  color: #0066ff;
}


.vg-reports-container .orange-circle {
  background: #fef3d6;
  color: #ff9f43;
}


.vg-reports-container .metric-data {
  display: flex;
  flex-direction: column;
}


.vg-reports-container .metric-number {
  font-size: 24px;
  font-weight: 800;
  line-height: 1.1;
}


.vg-reports-container .metric-label {
  font-size: 11px;

  font-weight: 700;

  letter-spacing: 0.5px;

  color: #8f9bba;

  margin-top: 4px;
}


.vg-reports-container .metric-subtext {
  font-size: 11px;

  font-weight: 600;

  margin-top: 3px;
}


/* =========================================================
   CARD
   ========================================================= */

.vg-reports-container .vg-card {
  background: #ffffff;

  border-radius: 12px;

  box-shadow: 0 4px 15px rgba(0,0,0,0.03);

  border: 1px solid #eef2f7;

  padding: 20px 24px;

  margin-bottom: 24px;
}


.vg-reports-container .vg-card-header {
  display: flex;

  justify-content: space-between;

  align-items: center;

  padding-bottom: 16px;

  border-bottom: 1px solid #f0f3f8;

  margin-bottom: 18px;
}


.vg-reports-container .vg-card-header h4 {
  margin: 0;

  font-size: 16px;

  font-weight: 700;

  color: #1b2559;
}


.vg-reports-container .vg-card-header h4 i {
  color: #0066ff;

  margin-right: 8px;
}


.vg-reports-container .chart-period {
  font-size: 11px;
  color: #8f9bba;
  font-weight: 600;
}


/* =========================================================
   FILTERS
   ========================================================= */

.vg-reports-container .filter-card {
  margin-bottom: 24px;
}


.vg-reports-container .filter-grid {
  display: grid;

  grid-template-columns:
    repeat(5, 1fr) auto;

  gap: 14px;

  align-items: end;
}


.vg-reports-container .filter-field label {
  display: block;

  font-size: 11px;

  font-weight: 700;

  color: #6b7280;

  margin-bottom: 6px;
}


.vg-reports-container .filter-field .form-control {
  height: 38px;

  border-radius: 8px;

  border: 1px solid #e0e5f2;

  background: #f8faff;

  font-size: 12px;

  color: #2b3674;
}


.vg-reports-container .filter-field .form-control:focus {
  background: #ffffff;

  border-color: #0066ff;

  box-shadow: none;
}


.vg-reports-container .btn-apply {
  height: 38px;

  background: #0066ff;

  border: 1px solid #0066ff;

  color: #ffffff;

  font-weight: 600;

  border-radius: 8px;

  padding: 0 18px;
}


.vg-reports-container .btn-apply:hover {
  background: #0055d6;
}


/* =========================================================
   TREND CHART
   ========================================================= */

.vg-reports-container .chart-card {
  min-height: 300px;
}


.vg-reports-container .trend-area {
  height: 205px;

  padding-top: 10px;
}


.vg-reports-container .trend-values {
  height: 100%;

  display: flex;

  align-items: flex-end;

  justify-content: space-around;

  border-bottom: 1px solid #eef2f7;

  gap: 12px;
}


.vg-reports-container .trend-column {
  height: 100%;

  flex: 1;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: flex-end;

  min-width: 30px;
}


.vg-reports-container .trend-value {
  font-size: 10px;

  color: #6b7280;

  font-weight: 700;

  margin-bottom: 5px;
}


.vg-reports-container .trend-track {
  height: 145px;

  width: 22px;

  background: #f4f7fe;

  border-radius: 6px 6px 0 0;

  display: flex;

  align-items: flex-end;
}


.vg-reports-container .trend-fill {
  width: 100%;

  border-radius: 6px 6px 0 0;

  min-height: 3px;

  transition: height 0.3s ease;
}


.vg-reports-container .compliance-fill {
  background: #00b074;
}


.vg-reports-container .volume-fill {
  background: #0066ff;
}


.vg-reports-container .trend-label {
  font-size: 10px;

  color: #8f9bba;

  margin-top: 7px;

  white-space: nowrap;
}


/* =========================================================
   RISK DISTRIBUTION
   ========================================================= */

.vg-reports-container .distribution-list {
  display: flex;

  flex-direction: column;

  gap: 20px;
}


.vg-reports-container .distribution-header {
  display: flex;

  justify-content: space-between;

  align-items: center;

  font-size: 13px;

  color: #1b2559;

  margin-bottom: 7px;
}


.vg-reports-container .distribution-header i {
  margin-right: 6px;
}


.vg-reports-container .risk-high-icon {
  color: #ea5455;
}


.vg-reports-container .risk-medium-icon {
  color: #ff9f43;
}


.vg-reports-container .risk-low-icon {
  color: #00b074;
}


.vg-reports-container .distribution-track {
  width: 100%;

  height: 9px;

  background: #f4f7fe;

  border-radius: 10px;
}


.vg-reports-container .distribution-fill {
  height: 100%;

  border-radius: 10px;
}


.vg-reports-container .risk-high-bar {
  background: #ea5455;
}


.vg-reports-container .risk-medium-bar {
  background: #ff9f43;
}


.vg-reports-container .risk-low-bar {
  background: #00b074;
}


.vg-reports-container .distribution-percent {
  font-size: 10px;

  color: #8f9bba;

  text-align: right;

  margin-top: 4px;
}


/* =========================================================
   SLA
   ========================================================= */

.vg-reports-container .sla-summary {
  display: flex;

  align-items: center;

  gap: 35px;

  padding: 12px 10px;
}


.vg-reports-container .sla-circle {
  width: 125px;

  height: 125px;

  border-radius: 50%;

  border: 12px solid #00b074;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;
}


.vg-reports-container .sla-circle span {
  font-size: 24px;

  font-weight: 800;

  color: #1b2559;
}


.vg-reports-container .sla-circle small {
  font-size: 10px;

  color: #8f9bba;

  font-weight: 600;
}


.vg-reports-container .sla-details {
  width: 100%;
}


.vg-reports-container .sla-detail-row {
  display: flex;

  justify-content: space-between;

  padding: 11px 0;

  border-bottom: 1px solid #f0f3f8;

  font-size: 12px;
}


.vg-reports-container .sla-detail-row:last-child {
  border-bottom: none;
}


/* =========================================================
   TABLE
   ========================================================= */

.vg-reports-container .vg-table {
  margin: 0;
}


.vg-reports-container .vg-table th {
  font-size: 11px;

  text-transform: uppercase;

  font-weight: 700;

  color: #8f9bba;

  letter-spacing: 0.5px;

  border-bottom: 2px solid #eef2f7;

  border-top: none;

  padding: 12px 8px;
}


.vg-reports-container .vg-table td {
  vertical-align: middle;

  font-size: 13px;

  color: #2b3674;

  border-top: 1px solid #f4f7fe;

  padding: 13px 8px;
}


.vg-reports-container .issue-progress {
  width: 120px;

  height: 7px;

  display: inline-block;

  vertical-align: middle;

  background: #f4f7fe;

  border-radius: 10px;

  margin-right: 8px;
}


.vg-reports-container .issue-progress-fill {
  height: 100%;

  background: #0066ff;

  border-radius: 10px;
}


.vg-reports-container .issue-percent {
  font-size: 11px;

  color: #8f9bba;
}


.vg-reports-container .status-pill {
  display: inline-block;

  padding: 4px 10px;

  border-radius: 20px;

  font-size: 11px;

  font-weight: 700;
}


.vg-reports-container .pill-green {
  background: #e6f4ea;

  color: #00b074;
}


.vg-reports-container .pill-orange {
  background: #fef3d6;

  color: #ff9f43;
}


.vg-reports-container .pill-red {
  background: #fde8e8;

  color: #ea5455;
}


.vg-reports-container .empty-row {
  padding: 30px !important;

  text-align: center;

  color: #8f9bba;
}


/* =========================================================
   CASE DISTRIBUTION
   ========================================================= */

.vg-reports-container .case-distribution {
  display: flex;

  flex-direction: column;

  gap: 10px;
}


.vg-reports-container .case-distribution-item {
  display: flex;

  align-items: center;

  padding: 12px;

  background: #f8faff;

  border: 1px solid #eef2f7;

  border-radius: 8px;

  gap: 12px;
}


.vg-reports-container .case-icon {
  width: 35px;

  height: 35px;

  border-radius: 8px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #e8f0fe;

  color: #0066ff;
}


.vg-reports-container .case-info {
  display: flex;

  flex-direction: column;

  flex: 1;
}


.vg-reports-container .case-info span {
  font-size: 11px;

  color: #8f9bba;
}


.vg-reports-container .case-info strong {
  font-size: 14px;

  color: #1b2559;
}


.vg-reports-container .case-percent {
  font-size: 12px;

  font-weight: 700;

  color: #0066ff;
}


/* =========================================================
   REPORT LIST
   ========================================================= */

.vg-reports-container .report-list {
  display: flex;

  flex-direction: column;

  gap: 10px;
}


.vg-reports-container .report-item {
  display: flex;

  align-items: center;

  gap: 12px;

  padding: 10px;

  border: 1px solid #eef2f7;

  border-radius: 8px;
}


.vg-reports-container .report-icon {
  width: 36px;

  height: 36px;

  border-radius: 8px;

  display: flex;

  align-items: center;

  justify-content: center;
}


.vg-reports-container .blue-bg {
  background: #e8f0fe;

  color: #0066ff;
}


.vg-reports-container .red-bg {
  background: #fde8e8;

  color: #ea5455;
}


.vg-reports-container .orange-bg {
  background: #fef3d6;

  color: #ff9f43;
}


.vg-reports-container .green-bg {
  background: #e6f4ea;

  color: #00b074;
}


.vg-reports-container .report-item div:last-child {
  display: flex;

  flex-direction: column;
}


.vg-reports-container .report-item strong {
  font-size: 12px;

  color: #1b2559;
}


.vg-reports-container .report-item span {
  font-size: 10px;

  color: #8f9bba;

  margin-top: 3px;
}


/* =========================================================
   SEARCH
   ========================================================= */

.vg-reports-container .search-wrapper {
  position: relative;
}


.vg-reports-container .search-icon {
  position: absolute;

  left: 10px;

  top: 9px;

  color: #8f9bba;

  font-size: 12px;

  z-index: 2;
}


.vg-reports-container .search-input {
  padding-left: 28px;

  border-radius: 8px;

  border: 1px solid #e0e5f2;

  background: #f4f7fe;

  font-size: 12px;

  width: 220px;
}


/* =========================================================
   AI INSIGHTS
   ========================================================= */

.vg-reports-container .ai-report-card {
  background: linear-gradient(
    135deg,
    #ffffff 0%,
    #f8faff 100%
  );
}


.vg-reports-container .ai-insight-content {
  display: flex;

  align-items: flex-start;

  gap: 18px;
}


.vg-reports-container .ai-icon {
  width: 48px;

  height: 48px;

  border-radius: 12px;

  background: #e8f0fe;

  color: #0066ff;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 21px;

  flex-shrink: 0;
}


.vg-reports-container .ai-text {
  flex: 1;
}


.vg-reports-container .ai-text strong {
  font-size: 14px;

  color: #1b2559;
}


.vg-reports-container .ai-text p {
  margin: 7px 0 12px;

  font-size: 13px;

  line-height: 1.6;

  color: #4a5568;
}


.vg-reports-container .recommendation {
  background: #f4f7fe;

  border-left: 4px solid #0066ff;

  border-radius: 0 7px 7px 0;

  padding: 10px 13px;

  display: flex;

  gap: 9px;

  align-items: center;

  font-size: 12px;

  color: #2b3674;
}


.vg-reports-container .recommendation i {
  color: #00b074;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

  .vg-reports-container .filter-grid {
    grid-template-columns: repeat(3, 1fr);
  }

}


@media (max-width: 768px) {

  .vg-reports-container .vg-hero-banner {
    flex-direction: column;

    align-items: flex-start;

    gap: 15px;
  }


  .vg-reports-container .filter-grid {
    grid-template-columns: 1fr;
  }


  .vg-reports-container .sla-summary {
    flex-direction: column;
  }


  .vg-reports-container .search-input {
    width: 180px;
  }

}

sp_widget.script:
(function() {

    /*
     * =========================================================
     * VISA GUARDIAN AI
     * REPORTS & INSIGHTS
     *
     * Data Source:
     * Visa Cases table
     *
     * The table is discovered using its LABEL instead of
     * hard-coding the application table name.
     * =========================================================
     */


    data.success = true;
    data.error = "";


    // =========================================================
    // INPUT ACTION
    // =========================================================

    var action = "";

    if (input && input.action) {
        action = String(input.action);
    }


    /*
     * Default
     */

    if (!action) {
        action = "refresh";
    }


    // =========================================================
    // FIND VISA CASE TABLE
    // =========================================================

    var tableName = findVisaCaseTable();

    data.tableName = tableName;


    if (!tableName) {

        data.success = false;

        data.error =
            "Visa Cases table could not be found. " +
            "Check that the table label is 'Visa Cases'.";

        setEmptyData();

        return;
    }


    // =========================================================
    // BUILD REPORT
    // =========================================================

    var filters = {};

    if (input && input.filters) {
        filters = input.filters;
    }


    buildReport(tableName, filters);



    // =========================================================
    // FIND VISA CASE TABLE
    // =========================================================

    function findVisaCaseTable() {

        /*
         * First search by table label.
         */

        var obj =
            new GlideRecord("sys_db_object");

        obj.addQuery(
            "label",
            "Visa Cases"
        );

        obj.setLimit(1);

        obj.query();


        if (obj.next()) {

            var name =
                obj.getValue("name");

            if (name) {

                var test =
                    new GlideRecord(name);

                if (test.isValid()) {
                    return name;
                }

            }

        }


        /*
         * Fallback:
         * Search application tables whose name contains
         * visaguardi and visa_case.
         */

        obj =
            new GlideRecord("sys_db_object");

        obj.addQuery(
            "name",
            "CONTAINS",
            "visaguardi"
        );

        obj.addQuery(
            "name",
            "CONTAINS",
            "visa"
        );

        obj.query();


        while (obj.next()) {

            var table =
                obj.getValue("name");

            if (
                table &&
                table.toLowerCase().indexOf("case") >= 0
            ) {

                var check =
                    new GlideRecord(table);

                if (check.isValid()) {
                    return table;
                }

            }

        }


        return "";
    }



    // =========================================================
    // BUILD REPORT
    // =========================================================

    function buildReport(tableName, filters) {

        var gr =
            new GlideRecord(tableName);


        if (!gr.isValid()) {

            data.success = false;

            data.error =
                "Visa Cases table is not accessible.";

            setEmptyData();

            return;
        }


        /*
         * Detect fields dynamically.
         */

        var fields = detectFields(gr);


        /*
         * Containers
         */

        var cases = [];

        var visaTypes = {};

        var statuses = {};

        var advisors = {};

        var riskCounts = {

            High: 0,

            Medium: 0,

            Low: 0

        };


        /*
         * Query all records.
         */

        gr.query();


        while (gr.next()) {

            var record =
                readCase(
                    gr,
                    fields
                );


            /*
             * Apply filters.
             */

            if (
                !passesFilters(
                    record,
                    filters
                )
            ) {
                continue;
            }


            cases.push(record);


            /*
             * Filter options
             */

            if (record.visa_type) {

                visaTypes[
                    record.visa_type
                ] = true;

            }


            if (record.status) {

                statuses[
                    record.status
                ] = true;

            }


            if (record.advisor) {

                advisors[
                    record.advisor
                ] = true;

            }


            /*
             * Risk
             */

            var normalizedRisk =
                normalizeRisk(
                    record.risk
                );


            if (normalizedRisk) {

                riskCounts[
                    normalizedRisk
                ]++;

            }

        }


        /*
         * =====================================================
         * KPI
         * =====================================================
         */

        var total =
            cases.length;


        var resolved =
            0;

        var highRisk =
            0;

        var slaGood =
            0;


        for (
            var i = 0;
            i < cases.length;
            i++
        ) {

            var current =
                cases[i];


            /*
             * Resolution
             */

            if (
                isResolvedStatus(
                    current.status
                )
            ) {

                resolved++;

            }


            /*
             * High risk
             */

            if (
                normalizeRisk(
                    current.risk
                ) === "High"
            ) {

                highRisk++;

            }


            /*
             * SLA
             */

            if (
                isSlaGood(
                    current
                )
            ) {

                slaGood++;

            }

        }


        var compliance =
            calculateCompliance(
                cases
            );


        var resolution =
            percentage(
                resolved,
                total
            );


        var sla =
            percentage(
                slaGood,
                total
            );


        /*
         * =====================================================
         * KPI DATA
         * =====================================================
         */

        data.kpis = {

            compliance: compliance,

            highRisk: highRisk,

            resolution: resolution,

            sla: sla

        };


        /*
         * =====================================================
         * RISK DISTRIBUTION
         * =====================================================
         */

        data.caseDistribution = [

            {

                label: "High Risk",

                count: riskCounts.High,

                percentage:
                    percentage(
                        riskCounts.High,
                        total
                    ),

                color: "red"

            },

            {

                label: "Medium Risk",

                count: riskCounts.Medium,

                percentage:
                    percentage(
                        riskCounts.Medium,
                        total
                    ),

                color: "orange"

            },

            {

                label: "Low Risk",

                count: riskCounts.Low,

                percentage:
                    percentage(
                        riskCounts.Low,
                        total
                    ),

                color: "green"

            }

        ];


        /*
         * =====================================================
         * MONTHLY CASE VOLUME
         * =====================================================
         */

        data.caseVolume =
            buildMonthlyVolume(
                cases
            );


        /*
         * =====================================================
         * COMPLIANCE TREND
         * =====================================================
         */

        data.complianceTrend =
            buildComplianceTrend(
                cases
            );


        /*
         * =====================================================
         * RISK TREND
         * =====================================================
         */

        data.riskTrend =
            buildRiskTrend(
                cases
            );


        /*
         * =====================================================
         * SLA TREND
         * =====================================================
         */

        data.slaTrend =
            buildSlaTrend(
                cases
            );


        /*
         * =====================================================
         * COMPLIANCE ISSUES
         * =====================================================
         */

        data.complianceIssues =
            buildComplianceIssues(
                cases
            );


        /*
         * =====================================================
         * FILTER OPTIONS
         * =====================================================
         */

        data.filterOptions = {

            visaTypes:
                objectToArray(
                    visaTypes
                ),

            statuses:
                objectToArray(
                    statuses
                ),

            advisors:
                objectToArray(
                    advisors
                )

        };


        /*
         * =====================================================
         * AI INSIGHTS
         * =====================================================
         */

        data.aiInsights =
            buildAIInsights(
                cases,
                total,
                highRisk,
                resolved,
                slaGood
            );


        /*
         * =====================================================
         * CASE SUMMARY
         * =====================================================
         */

        data.totalCases =
            total;

    }



    // =========================================================
    // DETECT FIELDS
    // =========================================================

