    // =========================================================
    // READ CASE
    // =========================================================

    function readCase(gr, fields) {

        var record = {

            case_id: "",

            student: "",

            visa_type: "",

            status: "",

            risk: "",

            priority: "",

            advisor: "",

            created: "",

            deadline: "",

            document: ""

        };


        record.case_id =
            displayValue(
                gr,
                fields.caseId
            );


        record.student =
            displayValue(
                gr,
                fields.student
            );


        record.visa_type =
            displayValue(
                gr,
                fields.visaType
            );


        record.status =
            displayValue(
                gr,
                fields.status
            );


        record.risk =
            displayValue(
                gr,
                fields.risk
            );


        record.priority =
            displayValue(
                gr,
                fields.priority
            );


        record.advisor =
            displayValue(
                gr,
                fields.advisor
            );


        record.created =
            displayValue(
                gr,
                fields.created
            );


        record.deadline =
            displayValue(
                gr,
                fields.deadline
            );


        record.document =
            displayValue(
                gr,
                fields.document
            );


        /*
         * Also preserve the raw created date.
         */

        record.createdRaw = "";

        if (fields.created) {

            record.createdRaw =
                gr.getValue(
                    fields.created
                );

        }


        return record;

    }



    // =========================================================
    // FILTERS
    // =========================================================

    function passesFilters(
        record,
        filters
    ) {

        if (!filters) {
            return true;
        }


        /*
         * Visa
         */

        if (
            filters.visaType &&
            filters.visaType !== "ALL"
        ) {

            if (
                record.visa_type !==
                filters.visaType
            ) {

                return false;

            }

        }


        /*
         * Status
         */

        if (
            filters.caseStatus &&
            filters.caseStatus !== "ALL"
        ) {

            if (
                record.status !==
                filters.caseStatus
            ) {

                return false;

            }

        }


        /*
         * Advisor
         */

        if (
            filters.advisor &&
            filters.advisor !== "ALL"
        ) {

            if (
                record.advisor !==
                filters.advisor
            ) {

                return false;

            }

        }


        /*
         * Risk
         */

        if (
            filters.risk &&
            filters.risk !== "ALL"
        ) {

            if (
                normalizeRisk(
                    record.risk
                ) !==
                filters.risk
            ) {

                return false;

            }

        }


        /*
         * Date
         */

        if (
            filters.dateRange &&
            filters.dateRange !== "ALL"
        ) {

            var days =
                parseInt(
                    filters.dateRange,
                    10
                );


            if (!isNaN(days)) {

                if (
                    record.createdRaw
                ) {

                    var created =
                        new GlideDateTime(
                            record.createdRaw
                        );


                    var cutoff =
                        new GlideDateTime();


                    cutoff.addDaysUTC(
                        -days
                    );


                    if (
                        created.before(
                            cutoff
                        )
                    ) {

                        return false;

                    }

                }

            }

        }


        return true;

    }



    // =========================================================
    // COMPLIANCE
    // =========================================================

    function calculateCompliance(
        cases
    ) {

        if (!cases.length) {
            return 0;
        }


        var good = 0;


        for (
            var i = 0;
            i < cases.length;
            i++
        ) {

            var c =
                cases[i];


            if (
                isCompliantCase(
                    c
                )
            ) {

                good++;

            }

        }


        return percentage(
            good,
            cases.length
        );

    }



    function isCompliantCase(
        record
    ) {

        var status =
            String(
                record.status || ""
            ).toLowerCase();


        var risk =
            normalizeRisk(
                record.risk
            );


        /*
         * Explicit problematic statuses.
         */

        if (
            status.indexOf("non-compliant") >= 0 ||
            status.indexOf("non compliant") >= 0 ||
            status.indexOf("rejected") >= 0 ||
            status.indexOf("problem") >= 0
        ) {

            return false;

        }


        /*
         * High risk is considered not compliant.
         */

        if (
            risk === "High"
        ) {

            return false;

        }


        return true;

    }



    // =========================================================
    // RESOLUTION
    // =========================================================

    function isResolvedStatus(
        status
    ) {

        var value =
            String(
                status || ""
            ).toLowerCase();


        return (
            value.indexOf("resolved") >= 0 ||
            value.indexOf("approved") >= 0 ||
            value.indexOf("closed") >= 0 ||
            value.indexOf("complete") >= 0
        );

    }



    // =========================================================
    // SLA
    // =========================================================

    function isSlaGood(
        record
    ) {

        var status =
            String(
                record.status || ""
            ).toLowerCase();


        /*
         * Resolved/approved/closed cases
         * are treated as completed within SLA
         * unless the deadline has passed.
         */

        if (
            isResolvedStatus(
                record.status
            )
        ) {

            return true;

        }


        /*
         * Check deadline.
         */

        if (
            record.deadline
        ) {

            try {

                var deadline =
                    new GlideDateTime(
                        record.deadline
                    );


                var now =
                    new GlideDateTime();


                if (
                    deadline.before(
                        now
                    )
                ) {

                    return false;

                }


                return true;

            }
            catch (e) {

                return true;

            }

        }


        /*
         * If no deadline exists,
         * treat as on track.
         */

        return true;

    }



    // =========================================================
    // MONTHLY VOLUME
    // =========================================================

    function buildMonthlyVolume(
        cases
    ) {

        var months = [];

        var now =
            new GlideDateTime();


        /*
         * Six months
         */

        for (
            var i = 5;
            i >= 0;
            i--
        ) {

            var d =
                new GlideDateTime();

            d.addMonthsUTC(
                -i
            );


            var key =
                d.getYearUTC() +
                "-" +
                pad(
                    d.getMonthUTC()
                );


            months.push({

                key: key,

                month:
                    monthName(
                        d.getMonthUTC()
                    ),

                value: 0,

                height: 0

            });

        }


        /*
         * Count cases.
         */

        for (
            var j = 0;
            j < cases.length;
            j++
        ) {

            if (
                !cases[j].createdRaw
            ) {
                continue;
            }


            var created =
                new GlideDateTime(
                    cases[j].createdRaw
                );


            var key =
                created.getYearUTC() +
                "-" +
                pad(
                    created.getMonthUTC()
                );


            for (
                var k = 0;
                k < months.length;
                k++
            ) {

                if (
                    months[k].key ===
                    key
                ) {

                    months[k].value++;

                    break;

                }

            }

        }


        /*
         * Calculate bar height.
         */

        var max = 1;


        for (
            var x = 0;
            x < months.length;
            x++
        ) {

            if (
                months[x].value >
                max
            ) {

                max =
                    months[x].value;

            }

        }


        for (
            var y = 0;
            y < months.length;
            y++
        ) {

            months[y].height =
                Math.round(
                    (
                        months[y].value /
                        max
                    ) * 100
                );

        }


        return months;

    }



    // =========================================================
    // COMPLIANCE TREND
    // =========================================================

    function buildComplianceTrend(
        cases
    ) {

        var result = [];


        for (
            var i = 5;
            i >= 0;
            i--
        ) {

            var d =
                new GlideDateTime();

            d.addMonthsUTC(
                -i
            );


            var year =
                d.getYearUTC();


            var month =
                d.getMonthUTC();


            var total = 0;

            var compliant = 0;


            for (
                var j = 0;
                j < cases.length;
                j++
            ) {

                if (
                    !cases[j].createdRaw
                ) {
                    continue;
                }


                var created =
                    new GlideDateTime(
                        cases[j].createdRaw
                    );


                if (
                    created.getYearUTC() ===
                    year &&
                    created.getMonthUTC() ===
                    month
                ) {

                    total++;


                    if (
                        isCompliantCase(
                            cases[j]
                        )
                    ) {

                        compliant++;

                    }

                }

            }


            var value = 0;


            if (total > 0) {

                value =
                    percentage(
                        compliant,
                        total
                    );

            }


            result.push({

                month:
                    monthName(
                        month
                    ),

                value: value

            });

        }


        return result;

    }



    // =========================================================
    // RISK TREND
    // =========================================================

    function buildRiskTrend(
        cases
    ) {

        var result = [];


        for (
            var i = 5;
            i >= 0;
            i--
        ) {

            var d =
                new GlideDateTime();

            d.addMonthsUTC(
                -i
            );


            var year =
                d.getYearUTC();


            var month =
                d.getMonthUTC();


            var total = 0;

            var high = 0;


            for (
                var j = 0;
                j < cases.length;
                j++
            ) {

                if (
                    !cases[j].createdRaw
                ) {
                    continue;
                }


                var created =
                    new GlideDateTime(
                        cases[j].createdRaw
                    );


                if (
                    created.getYearUTC() ===
                    year &&
                    created.getMonthUTC() ===
                    month
                ) {

                    total++;


                    if (
                        normalizeRisk(
                            cases[j].risk
                        ) === "High"
                    ) {

                        high++;

                    }

                }

            }


            result.push({

                month:
                    monthName(
                        month
                    ),

                value:
                    percentage(
                        high,
                        total
                    )

            });

        }


        return result;

    }



    // =========================================================
    // SLA TREND
    // =========================================================

    function buildSlaTrend(
        cases
    ) {

        var result = [];


        for (
            var i = 5;
            i >= 0;
            i--
        ) {

            var d =
                new GlideDateTime();

            d.addMonthsUTC(
                -i
            );


            var year =
                d.getYearUTC();


            var month =
                d.getMonthUTC();


            var total = 0;

            var good = 0;


            for (
                var j = 0;
                j < cases.length;
                j++
            ) {

                if (
                    !cases[j].createdRaw
                ) {
                    continue;
                }


                var created =
                    new GlideDateTime(
                        cases[j].createdRaw
                    );


                if (
                    created.getYearUTC() ===
                    year &&
                    created.getMonthUTC() ===
                    month
                ) {

                    total++;


                    if (
                        isSlaGood(
                            cases[j]
                        )
                    ) {

                        good++;

                    }

                }

            }


            result.push({

                month:
                    monthName(
                        month
                    ),

                value:
                    percentage(
                        good,
                        total
                    )

            });

        }


        return result;

    }



    // =========================================================
    // COMPLIANCE ISSUES
    // =========================================================

    function buildComplianceIssues(
        cases
    ) {

        var missingDocuments = 0;

        var highRisk = 0;

        var overdue = 0;

        var pending = 0;


        for (
            var i = 0;
            i < cases.length;
            i++
        ) {

            var c =
                cases[i];


            /*
             * Documents
             */

            var document =
                String(
                    c.document || ""
                ).toLowerCase();


            if (
                document.indexOf("missing") >= 0 ||
                document.indexOf("incomplete") >= 0 ||
                document.indexOf("expired") >= 0
            ) {

                missingDocuments++;

            }


            /*
             * Risk
             */

            if (
                normalizeRisk(
                    c.risk
                ) === "High"
            ) {

                highRisk++;

            }


            /*
             * Deadline
             */

            if (
                c.deadline
            ) {

                try {

                    var deadline =
                        new GlideDateTime(
                            c.deadline
                        );


                    var now =
                        new GlideDateTime();


                    if (
                        deadline.before(
                            now
                        ) &&
                        !isResolvedStatus(
                            c.status
                        )
                    ) {

                        overdue++;

                    }

                }
                catch (e) {}

            }


            /*
             * Pending
             */

            if (
                isPendingStatus(
                    c.status
                )
            ) {

                pending++;

            }

        }


        var total =
            cases.length;


        var issues = [];


        if (
            missingDocuments > 0
        ) {

            issues.push({

                issue:
                    "Document Compliance Gaps",

                description:
                    "Missing, incomplete or expired documentation",

                count:
                    missingDocuments,

                percentage:
                    percentage(
                        missingDocuments,
                        total
                    ),

                severity:
                    "High",

                status:
                    "Open"

            });

        }


        if (
            highRisk > 0
        ) {

            issues.push({

                issue:
                    "High-Risk Cases",

                description:
                    "Cases requiring enhanced review",

                count:
                    highRisk,

                percentage:
                    percentage(
                        highRisk,
                        total
                    ),

                severity:
                    "High",

                status:
                    "Monitor"

            });

        }


        if (
            overdue > 0
        ) {

            issues.push({

                issue:
                    "Overdue Cases",

                description:
                    "Cases with deadlines already passed",

                count:
                    overdue,

                percentage:
                    percentage(
                        overdue,
                        total
                    ),

                severity:
                    "High",

                status:
                    "Open"

            });

        }


        if (
            pending > 0
        ) {

            issues.push({

                issue:
                    "Pending Cases",

                description:
                    "Cases awaiting processing or review",

                count:
                    pending,

                percentage:
                    percentage(
                        pending,
                        total
                    ),

                severity:
                    "Medium",

                status:
                    "Monitor"

            });

        }


        return issues;

    }



    // =========================================================
    // AI INSIGHTS
    // =========================================================

    function buildAIInsights(
        cases,
        total,
        highRisk,
        resolved,
        slaGood
    ) {

        var insights = [];


        if (!total) {

            insights.push({

                title:
                    "No case data",

                text:
                    "There are currently no Visa Case records available for analysis."

            });

            return insights;

        }


        /*
         * Risk
         */

        if (
            highRisk > 0
        ) {

            insights.push({

                title:
                    "High-risk workload",

                text:
                    highRisk +
                    " of " +
                    total +
                    " cases are currently classified as high risk. These cases should receive priority review."

            });

        }
        else {

            insights.push({

                title:
                    "Risk profile",

                text:
                    "No high-risk cases were identified in the current Visa Case dataset."

            });

        }


        /*
         * Resolution
         */

        var resolution =
            percentage(
                resolved,
                total
            );


        insights.push({

            title:
                "Case resolution",

            text:
                resolution +
                "% of the current cases are in a resolved, approved, closed or completed state."

        });


        /*
         * SLA
         */

        var sla =
            percentage(
                slaGood,
                total
            );


        insights.push({

            title:
                "SLA performance",

            text:
                sla +
                "% of current cases are currently within their expected deadline or have already been completed."

        });


        return insights;

    }



    // =========================================================
    // HELPERS
    // =========================================================

    function findField(
        gr,
        possibleFields
    ) {

        for (
            var i = 0;
            i < possibleFields.length;
            i++
        ) {

            if (
                gr.isValidField(
                    possibleFields[i]
                )
            ) {

                return possibleFields[i];

            }

        }


        return "";

    }



    function displayValue(
        gr,
        field
    ) {

        if (
            !field ||
            !gr.isValidField(field)
        ) {

            return "";

        }


        var value =
            gr.getDisplayValue(
                field
            );


        if (!value) {

            value =
                gr.getValue(
                    field
                );

        }


        return value || "";

    }



    function normalizeRisk(
        value
    ) {

        var risk =
            String(
                value || ""
            ).toLowerCase();


        if (
            risk.indexOf("high") >= 0 ||
            risk.indexOf("critical") >= 0
        ) {

            return "High";

        }


        if (
            risk.indexOf("medium") >= 0 ||
            risk.indexOf("moderate") >= 0
        ) {

            return "Medium";

        }


        if (
            risk.indexOf("low") >= 0 ||
            risk.indexOf("normal") >= 0
        ) {

            return "Low";

        }


        return "";

    }



    function isPendingStatus(
        status
    ) {

        var value =
            String(
                status || ""
            ).toLowerCase();


        return (
            value.indexOf("pending") >= 0 ||
            value.indexOf("open") >= 0 ||
            value.indexOf("review") >= 0 ||
            value.indexOf("progress") >= 0
        );

    }



    function percentage(
        part,
        total
    ) {

        if (
            !total ||
            total <= 0
        ) {

            return 0;

        }


        return Math.round(
            (
                part /
                total
            ) * 100
        );

    }



    function objectToArray(
        object
    ) {

        var result = [];


        for (
            var key in object
        ) {

            if (
                object.hasOwnProperty(
                    key
                )
            ) {

                result.push(
                    key
                );

            }

        }


        result.sort();


        return result;

    }



    function pad(
        number
    ) {

        return number < 10
            ? "0" + number
            : String(number);

    }



    function monthName(
        month
    ) {

        var months = [

            "Jan",
            "Feb",
            "Mar",
            "Apr",
            "May",
            "Jun",
            "Jul",
            "Aug",
            "Sep",
            "Oct",
            "Nov",
            "Dec"

        ];


        /*
         * ServiceNow getMonthUTC()
         * is generally 1-12.
         */

        var index =
            parseInt(
                month,
                10
            ) - 1;


        return months[index] || "";

    }



    // =========================================================
    // EMPTY DATA
    // =========================================================

    function setEmptyData() {

        data.kpis = {

            compliance: 0,

            highRisk: 0,

            resolution: 0,

            sla: 0

        };


        data.totalCases = 0;


        data.caseDistribution = [

            {
                label: "High Risk",
                count: 0,
                percentage: 0,
                color: "red"
            },

            {
                label: "Medium Risk",
                count: 0,
                percentage: 0,
                color: "orange"
            },

            {
                label: "Low Risk",
                count: 0,
                percentage: 0,
                color: "green"
            }

        ];


        data.caseVolume = [];

        data.complianceTrend = [];

        data.riskTrend = [];

        data.slaTrend = [];

        data.complianceIssues = [];

        data.aiInsights = [];

        data.filterOptions = {

            visaTypes: [],

            statuses: [],

            advisors: []

        };

    }

})();
